<script setup lang="ts">
import {exportRows,downloadCsv} from '../../utils/export'
import {ref,onMounted} from 'vue'
import {http} from '../../api/http'
import {day} from '../../utils/dates'
import type {Row} from '../../shared/records'
const dateFrom=ref(day().slice(0,8)+'01'),dateTo=ref(day()),keyword=ref(''),rows=ref<Row[]>([]),summary=ref<Row>({}),total=ref(0),page=ref(1),pending=ref(false),error=ref('')
let generation=0
async function load(){const request=++generation;pending.value=true;error.value='';try{const data=await http.get<never,Row>('/billing',{params:{dateFrom:dateFrom.value,dateTo:dateTo.value,keyword:keyword.value,page:page.value,size:20}});if(request!==generation)return;rows.value=data.records;total.value=data.total;summary.value=data.summary}catch(e){if(request===generation)error.value=(e as Error).message}finally{if(request===generation)pending.value=false}}
async function exportAll(){pending.value=true;error.value='';try{const all=await exportRows('/billing',{dateFrom:dateFrom.value,dateTo:dateTo.value,keyword:keyword.value});downloadCsv('支付与消费账单',['时间','类型','订单号','老人','订单原价','订单补贴','交易金额','渠道'],all.map(r=>[new Date(r.eventAt).toLocaleString('zh-CN'),r.entryType==='PAYMENT'?'支付':'退款',r.orderNo,r.elderName,r.originalAmount,r.subsidyAmount,r.amount,r.channel]))}catch(e){error.value=(e as Error).message}finally{pending.value=false}}
onMounted(load)
</script>
<template><section><p class="eyebrow">账户账单</p><h1>支付与消费账单</h1><p class="muted">按实际支付和退款日期记录本人资金支出。钱包充值和未支付订单不计入消费。</p><div class="toolbar"><label for="billing-from">开始日期</label><el-input id="billing-from" v-model="dateFrom" type="date"/><label for="billing-to">结束日期</label><el-input id="billing-to" v-model="dateTo" type="date"/><el-input v-model="keyword" aria-label="账单关键词" placeholder="订单号或老人姓名"/><el-button type="primary" :loading="pending" @click="page=1;load()">查询账单</el-button><el-button :loading="pending" @click="exportAll">导出账单 CSV</el-button><router-link class="text-link" to="/family/orders">查看订单与待付款 →</router-link></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="info-grid"><article v-for="(label,key) in {paidAmount:'成功支付',refundAmount:'成功退款',netExpense:'净支出'}" :key="key" class="content-card"><p>{{label}}</p><h2>¥{{summary[key]??'—'}}</h2></article></div><el-table :data="rows" empty-text="所选期间暂无支付或退款记录" style="margin-top:24px"><el-table-column label="时间" min-width="180"><template #default="{row}">{{new Date(row.eventAt).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column label="类型"><template #default="{row}">{{row.entryType==='PAYMENT'?'支付':'退款'}}</template></el-table-column><el-table-column prop="elderName" label="老人"/><el-table-column prop="originalAmount" label="订单原价"/><el-table-column prop="subsidyAmount" label="订单补贴"/><el-table-column prop="amount" label="实际交易金额"/><el-table-column label="渠道"><template #default="{row}">{{row.channel==='WALLET'?'钱包余额':row.channel==='MOCK_A'?'演示支付 A':'演示支付 B'}}</template></el-table-column><el-table-column label="订单" min-width="200"><template #default="{row}"><router-link class="text-link" :to="{path:'/family/orders',query:{orderId:row.orderId}}">{{row.orderNo}}</router-link></template></el-table-column></el-table><div class="toolbar"><span>共 {{total}} 条</span><el-button :disabled="page===1" @click="page--;load()">上一页</el-button><span>{{page}}</span><el-button :disabled="page*20>=total" @click="page++;load()">下一页</el-button></div></section></template>
